WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT p.pedido_id, p.cliente, p.site, p.status, p.segmento, p.segmento_origem, COALESCE(e.nome, 'não informado') AS executivo, p.produtos, p.preco, p.fonte, p.portal_url, p.banners_situacao, p.erro_codigo, p.produtos_similares, p.simulado, p.criado_em, p.concluido_em, p.execucao_acao, (p.execucao_atual IS NOT NULL) AS em_execucao FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) LEFT JOIN executivos e ON e.id = p.executivo_id WHERE (NOT eu.admin OR :executivo IS NULL OR :executivo = '' OR p.executivo_id = CAST(:executivo AS INTEGER)) AND (:segmento IS NULL OR :segmento = '' OR p.segmento = :segmento) AND (:status IS NULL OR :status = '' OR p.status = :status) AND (:desde IS NULL OR :desde = '' OR p.criado_em >= CAST(:desde AS DATE)) AND (:ate IS NULL OR :ate = '' OR p.criado_em < CAST(:ate AS DATE) + 1) AND (:busca IS NULL OR :busca = '' OR p.cliente ILIKE '%' || :busca || '%') ORDER BY p.criado_em DESC LIMIT CAST(:limite AS INTEGER) OFFSET CAST(:offset AS INTEGER)
